import React, { useState, useEffect, useCallback } from 'react';
import { useParams } from 'react musical-dom';
import { useParams as useReactParams } from 'react-router-dom';
import axios from 'axios';
import { User, Settings, Heart, MessageCircle, Edit3, X, Check } from 'lucide-react';

const API_BASE = process.env.REACT_APP_SERVER_URL || 'http://localhost:5000';

const Profile = ({ currentUser, onUpdateUser }) => {
  const { username } = useReactParams();
  const [profileData, setProfileData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [isFollowing, setIsFollowing] = useState(false);

  // Edit profile state
  const [isEditOpen, setIsEditOpen] = useState(false);
  const [bioInput, setBioInput] = useState('');
  const [profilePicInput, setProfilePicInput] = useState('');
  const [updating, setUpdating] = useState(false);

  const fetchProfile = useCallback(async () => {
    try {
      const res = await axios.get(`/users/${username}`);
      setProfileData(res.data);

      if (currentUser && res.data.user) {
        setIsFollowing(res.data.user.followers?.includes(currentUser._id || currentUser.id));
        setBioInput(res.data.user.bio || '');
        setProfilePicInput(res.data.user.profilePic || '');
      }
    } catch (err) {
      console.error('Failed to load profile:', err);
    } finally {
      setLoading(false);
    }
  }, [username, currentUser]);

  useEffect(() => {
    fetchProfile();
  }, [fetchProfile]);

  const handleFollowToggle = async () => {
    if (!profileData?.user) return;
    try {
      const res = await axios.put(`/users/${profileData.user._id}/follow`);
      setIsFollowing(res.data.isFollowing);
      setProfileData(prev => ({
        ...prev,
        user: {
          ...prev.user,
          followers: res.data.isFollowing
            ? [...(prev.user.followers || []), currentUser._id]
            : (prev.user.followers || []).filter(id => id !== currentUser._id)
        }
      }));
    } catch (err) {
      console.error('Follow failed:', err);
    }
  };

  const handleUpdateProfile = async (e) => {
    e.preventDefault();
    setUpdating(true);
    try {
      const res = await axios.put('/users/profile', {
        bio: bioInput,
        profilePic: profilePicInput
      });

      setProfileData(prev => ({
        ...prev,
        user: { ...prev.user, bio: res.data.bio, profilePic: res.data.profilePic }
      }));

      if (onUpdateUser) {
        onUpdateUser(res.data);
      }
      setIsEditOpen(false);
    } catch (err) {
      alert('Failed to update profile');
    } finally {
      setUpdating(false);
    }
  };

  const getImageUrl = (imagePath) => {
    if (!imagePath) return '';
    if (imagePath.startsWith('http')) return imagePath;
    const cleanPath = imagePath.replace(/\\/g, '/');
    return `${API_BASE}/${cleanPath}`;
  };

  if (loading) {
    return (
      <div style={{ textAlign: 'center', padding: '60px', color: '#9ca3af' }}>
        <p>Loading profile...</p>
      </div>
    );
  }

  if (!profileData || !profileData.user) {
    return (
      <div style={{ textAlign: 'center', padding: '60px', color: '#9ca3af' }}>
        <h2>User Not Found</h2>
        <p>The account @{username} does not exist or has been removed.</p>
      </div>
    );
  }

  const { user, posts } = profileData;
  const isSelf = currentUser?.username === user.username;

  return (
    <div style={{ maxWidth: '935px', margin: '40px auto', padding: '0 20px' }}>

      {/* Profile Header */}
      <header className="glass-card" style={{ padding: '36px 30px', marginBottom: '40px' }}>
        <div style={{ display: 'flex', gap: '40px', alignItems: 'center', flexWrap: 'wrap' }}>

          {/* Avatar with Story Ring */}
          <div className="story-ring" style={{ padding: '4px' }}>
            {user.profilePic ? (
              <img
                src={user.profilePic}
                alt={user.username}
                className="story-avatar"
                style={{ width: '130px', height: '130px' }}
              />
            ) : (
              <div
                className="story-avatar"
                style={{ width: '130px', height: '130px', background: '#252530', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
              >
                <User size={60} color="#9ca3af" />
              </div>
            )}
          </div>

          {/* User Details & Bio */}
          <div style={{ flex: 1, minWidth: '260px' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '20px', marginBottom: '20px', flexWrap: 'wrap' }}>
              <h2 style={{ fontSize: '1.8rem', fontWeight: '400', color: '#fff' }}>{user.username}</h2>

              {isSelf ? (
                <button onClick={() => setIsEditOpen(true)} className="btn-secondary" style={{ padding: '8px 16px' }}>
                  <Edit3 size={16} />
                  <span>Edit Profile</span>
                </button>
              ) : (
                <button
                  onClick={handleFollowToggle}
                  className={isFollowing ? 'btn-secondary' : 'btn-primary'}
                  style={{ padding: '8px 24px' }}
                >
                  {isFollowing ? 'Following' : 'Follow'}
                </button>
              )}
            </div>

            {/* Stats Bar */}
            <div style={{ display: 'flex', gap: '36px', marginBottom: '20px', fontSize: '1rem', color: '#e5e7eb' }}>
              <div><strong style={{ color: '#fff' }}>{posts?.length || 0}</strong> posts</div>
              <div><strong style={{ color: '#fff' }}>{user.followers?.length || 0}</strong> followers</div>
              <div><strong style={{ color: '#fff' }}>{user.following?.length || 0}</strong> following</div>
            </div>

            {/* Bio */}
            <div>
              <p style={{ fontWeight: '600', color: '#f3f4f6', marginBottom: '4px' }}>{user.username}</p>
              <p style={{ color: '#9ca3af', fontSize: '0.95rem', whiteSpace: 'pre-line' }}>{user.bio || 'Welcome to my Nipix visual feed!'}</p>
            </div>
          </div>
        </div>
      </header>

      {/* Posts Grid Header */}
      <div style={{ borderTop: '1px solid var(--border-color)', marginBottom: '24px', textAlign: 'center' }}>
        <span style={{ display: 'inline-block', borderTop: '2px solid #fff', paddingTop: '12px', fontSize: '0.85rem', fontWeight: '700', letterSpacing: '1px', textTransform: 'uppercase', color: '#fff' }}>
          POSTS ({posts?.length || 0})
        </span>
      </div>

      {/* Posts Grid */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(260px, 1fr))', gap: '16px' }}>
        {posts?.length === 0 && (
          <div style={{ gridColumn: '1 / -1', textAlign: 'center', padding: '60px 0', color: '#9ca3af' }}>
            <p style={{ fontSize: '1.1rem' }}>No posts shared yet.</p>
          </div>
        )}

        {posts?.map(post => (
          <div
            key={post._id}
            className="glass-card"
            style={{ position: 'relative', aspectRatio: '1', cursor: 'pointer', overflow: 'hidden' }}
          >
            <img
              src={getImageUrl(post.image)}
              alt="post grid item"
              style={{ width: '100%', height: '100%', objectFit: 'cover', transition: 'transform 0.3s ease' }}
            />
            {/* Hover overlay with likes and comment count */}
            <div
              style={{
                position: 'absolute',
                top: 0, left: 0, right: 0, bottom: 0,
                background: 'rgba(0, 0, 0, 0.5)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                gap: '24px',
                color: '#fff',
                opacity: 0,
                transition: 'opacity 0.2s ease',
              }}
              onMouseEnter={(e) => e.currentTarget.style.opacity = 1}
              onMouseLeave={(e) => e.currentTarget.style.opacity = 0}
            >
              <div style={{ display: 'flex', alignItems: 'center', gap: '8px', fontWeight: '700' }}>
                <Heart size={20} fill="#fff" />
                <span>{post.likes?.length || 0}</span>
              </div>
              <div style={{ display: 'flex', alignItems: 'center', gap: '8px', fontWeight: '700' }}>
                <MessageCircle size={20} fill="#fff" />
                <span>{post.comments?.length || 0}</span>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Edit Profile Modal */}
      {isEditOpen && (
        <div className="modal-overlay" onClick={() => setIsEditOpen(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px', paddingBottom: '12px', borderBottom: '1px solid var(--border-color)' }}>
              <h3 style={{ fontSize: '1.2rem', fontWeight: '700', color: '#fff' }}>Edit Profile</h3>
              <button onClick={() => setIsEditOpen(false)} style={{ background: 'none', border: 'none', color: '#9ca3af', cursor: 'pointer' }}>
                <X size={24} />
              </button>
            </div>

            <form onSubmit={handleUpdateProfile} style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
              <div>
                <label style={{ display: 'block', marginBottom: '8px', fontSize: '0.85rem', color: '#9ca3af', fontWeight: '600' }}>Profile Picture URL</label>
                <input
                  type="url"
                  placeholder="https://example.com/avatar.jpg"
                  value={profilePicInput}
                  onChange={e => setProfilePicInput(e.target.value)}
                  className="input-field"
                />
              </div>

              <div>
                <label style={{ display: 'block', marginBottom: '8px', fontSize: '0.85rem', color: '#9ca3af', fontWeight: '600' }}>Bio</label>
                <textarea
                  rows={3}
                  placeholder="Tell your story..."
                  value={bioInput}
                  onChange={e => setBioInput(e.target.value)}
                  className="input-field"
                  style={{ resize: 'none' }}
                />
              </div>

              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '12px', marginTop: '12px' }}>
                <button type="button" onClick={() => setIsEditOpen(false)} className="btn-secondary">
                  Cancel
                </button>
                <button type="submit" disabled={updating} className="btn-primary">
                  {updating ? 'Saving...' : 'Save Changes'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Profile;
